mapper.update:
UPDATE env_oauth_flows
SET status = 'completed', credential_external_id = #{credentialExternalID},
    error_code = '', completed_at = #{completedAt}, updated_at = #{completedAt}
WHERE external_id = #{externalID}
AND status = 'pending'

UPDATE env_oauth_flows
SET status = 'failed', error_code = #{errorCode}, updated_at = #{failedAt}
WHERE external_id = #{externalID}
AND status = 'pending'
